import Foundation

// MARK: - Bus map (route paths)
//
// Same format as the subway map (SubwayMap, with an empty station list); each route draws the most common path for one direction.
// A copy ships with the app (Resources/bus_map.json, generated by tools/generate_bus.py);
// the first time the bus map is opened after the 1st of each month, the app downloads 6 bus feeds from MTA to check for updates (like the subway map).

public enum BusMap {
    /// MTA bus static GTFS: Bronx, Brooklyn, Manhattan, Queens, Staten Island, and MTA Bus Company (with their names in the source list)
    static let parts: [(code: String, name: String)] = [
        ("bx", "MTA Bus (Bronx)"), ("b", "MTA Bus (Brooklyn)"), ("m", "MTA Bus (Manhattan)"), ("q", "MTA Bus (Queens)"),
        ("si", "MTA Bus (Staten Island)"), ("busco", "MTA Bus Company"),
    ]

    /// The addresses in code, in that order
    public static let builtInSourceURLs: [URL] = parts.map {
        URL(string: "https://rrgtfsfeeds.s3.amazonaws.com/gtfs_\($0.code).zip")!
    }

    /// The addresses (the source list's, or the ones in code), in that order
    public static var sourceURLs: [URL] {
        zip(parts, builtInSourceURLs).map { SourceList.timetableURL(for: listID($0.0.code)) ?? $0.1 }
    }

    /// One part's ID in the source list, e.g. "mta-bus-bx"
    static func listID(_ code: String) -> String { "mta-bus-" + code }

    /// Only these files in the feed are needed (the huge stop_times.txt isn't read, saving memory).
    public static let neededFiles: Set<String> = ["routes.txt", "trips.txt", "shapes.txt", "feed_info.txt"]

    public static func loadBundled() throws -> SubwayMap {
        guard let url = Bundle.module.url(forResource: "bus_map", withExtension: "json") else {
            throw CocoaError(.fileNoSuchFile)
        }
        return try SubwayMap.decode(Data(contentsOf: url))
    }
}

/// Generate the bus map from bus GTFS (same approach as the map part of tools/generate_bus.py).
/// Processes one feed at a time and discards it when done, keeping memory use low.
public struct BusMapBuilder {
    /// Douglas-Peucker simplification tolerance, about 15 meters
    static let tolerance = 0.00015

    private var colors: [String: String] = [:]
    /// (route, direction) → shape ID → trip count
    private var shapeCounts: [String: [String: Int]] = [:]
    private var points: [String: [(Double, Double)]] = [:]
    private var version = ""

    public init() {}

    /// Add the files from one feed (routes.txt, trips.txt, shapes.txt, feed_info.txt optional).
    public mutating func add(files: [String: Data]) throws {
        for name in ["routes.txt", "trips.txt", "shapes.txt"] where files[name] == nil {
            throw TimetableError.missingFile(name)
        }
        try TimetableBuilder.forEachRow(files["routes.txt"]!) { col in
            guard let id = col("route_id"), colors[id] == nil else { return }
            let c = (col("route_color") ?? "").uppercased()
            colors[id] = c.isEmpty ? "0039A6" : c
        }
        var local: [String: [String: Int]] = [:]
        try TimetableBuilder.forEachRow(files["trips.txt"]!) { col in
            guard let route = col("route_id"), let shape = col("shape_id"), !shape.isEmpty else { return }
            let dir = col("direction_id").flatMap { $0.isEmpty ? nil : $0 } ?? "0"
            local[route + "|" + dir, default: [:]][shape, default: 0] += 1
        }
        // The most common shape for each route direction in this feed
        var wanted = Set<String>()
        for (key, counts) in local {
            shapeCounts[key, default: [:]].merge(counts, uniquingKeysWith: +)
            if let best = Self.mostCommon(counts) { wanted.insert(best) }
        }
        var raw: [String: [(Int, Double, Double)]] = [:]
        try TimetableBuilder.forEachRow(files["shapes.txt"]!) { col in
            guard let shape = col("shape_id"), wanted.contains(shape),
                  let seq = col("shape_pt_sequence").flatMap({ Int($0) }),
                  let lat = col("shape_pt_lat").flatMap({ Double($0) }),
                  let lon = col("shape_pt_lon").flatMap({ Double($0) }) else { return }
            raw[shape, default: []].append((seq, lat, lon))
        }
        for (shape, pts) in raw {
            points[shape] = pts.sorted { $0.0 < $1.0 }.map { ($0.1, $0.2) }
        }
        if let info = files["feed_info.txt"] {
            var first = true
            try TimetableBuilder.forEachRow(info) { col in
                if first { version = max(version, col("feed_version") ?? ""); first = false }
            }
        }
    }

    /// Generate the map: each route takes the most common shape in direction 0 (the other direction mostly overlaps, so it isn't drawn twice).
    public func build() throws -> SubwayMap {
        var routes: [SubwayMap.Route] = []
        for route in colors.keys.sorted() {
            guard let counts = shapeCounts[route + "|0"] ?? shapeCounts[route + "|1"],
                  let shape = Self.mostCommon(counts), let pts = points[shape] else { continue }
            let line = SubwayMapBuilder.simplify(pts, tolerance: Self.tolerance)
                .map { [SubwayMapBuilder.round5($0.0), SubwayMapBuilder.round5($0.1)] }
            guard line.count >= 2 else { continue }
            routes.append(SubwayMap.Route(route: route, color: colors[route] ?? "0039A6", lines: [line]))
        }
        guard !routes.isEmpty else { throw TimetableError.missingFile("shapes.txt") }
        return SubwayMap(source: "MTA bus static GTFS", feedVersion: version, stations: [], routes: routes)
    }

    /// The shape with the most trips (on a tie, the smaller ID, for stable results).
    static func mostCommon(_ counts: [String: Int]) -> String? {
        counts.max { a, b in a.value != b.value ? a.value < b.value : a.key > b.key }?.key
    }
}
